use super::*;
use std::os::unix::fs::symlink;
struct Fixture{root:PathBuf,docs:PathBuf,source:PathBuf}
impl Fixture{
 fn new()->Self{let root=std::env::temp_dir().join(format!("peggle-owned-raw-c50-{}",id()));fs::create_dir(&root).unwrap();let docs=root.join("Documents");let source=root.join("Selected");fs::create_dir(&docs).unwrap();fs::create_dir(&source).unwrap();Self{root,docs,source}}
 fn guest(&self)->PathBuf{Manager::guest(&self.docs)}
 fn put(&self,name:&str,b:&[u8])->PathBuf{let p=self.source.join(name);fs::write(&p,b).unwrap();p}
 fn pair(&self,name:&str,id:u32)->Vec<PathBuf>{vec![self.put("users.dat",&idx(&[(name,id)])),self.put(&format!("user{id}.dat"),&details(1))]}
 fn seed(&self,name:&str,id:u32){let g=self.guest();fs::create_dir_all(g.join("Documents/userdata")).unwrap();fs::write(g.join("Documents/userdata/users.dat"),idx(&[(name,id)])).unwrap();fs::write(g.join(format!("Documents/userdata/user{id}.dat")),details(1)).unwrap();fs::write(g.join("Documents/userdata/game_center.dat"),b"owned-account-stays-local").unwrap();fs::create_dir_all(g.join("Library/Preferences")).unwrap();let mut d=plist::Dictionary::new();d.insert("CurUser".into(),plist::Value::String(name.into()));d.insert("LocalAccount".into(),plist::Value::String("owned-local-only".into()));plist::Value::Dictionary(d).to_file_xml(g.join("Library/Preferences").join(format!("{GAME}.plist"))).unwrap();fs::create_dir_all(g.join("Library/Caches/empty")).unwrap();fs::write(g.join("Library/Caches/keep.bin"),b"owned-cache").unwrap();}
}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
fn idx(names:&[(&str,u32)])->Vec<u8>{encode_index(&names.iter().enumerate().map(|(n,(name,id))|Entry{name:(*name).into(),sequence:n as u32+1,id:*id}).collect::<Vec<_>>()).unwrap()}
fn details(value:u8)->Vec<u8>{let mut b=vec![value;494];b[..4].copy_from_slice(&25u32.to_le_bytes());b}
fn scores()->Vec<u8>{let mut b=Vec::from(3u32.to_le_bytes());b.extend_from_slice(&[0;8]);b}
fn board()->Vec<u8>{let mut b=Vec::from(87u32.to_le_bytes());b.push(1);b.extend_from_slice(&5u16.to_le_bytes());b.extend_from_slice(b"owned");b.resize(64,0);b}
fn stats()->Vec<u8>{let mut b=Vec::from(3u32.to_le_bytes());b.extend_from_slice(&[0;4]);b.extend_from_slice(&0u16.to_le_bytes());b.extend_from_slice(&[0;4+12*4+16*8]);b.extend_from_slice(&[0;8]);b.extend_from_slice(&[0;12*4+16*8]);b.extend_from_slice(&[0;4]);b}
fn replay()->Vec<u8>{let mut b=Vec::from(87u32.to_le_bytes());b.extend_from_slice(&0u16.to_le_bytes());b.extend_from_slice(&0u32.to_le_bytes());b.extend_from_slice(&1u16.to_le_bytes());b.extend_from_slice(&64u32.to_le_bytes());b.extend_from_slice(&board());b}
fn apply(m:&mut Manager,p:&Value){assert_eq!(p["can_import"],true,"{p}");m.restore_raw(p["token"].as_str().unwrap(),true).unwrap();}
fn selected(m:&Manager)->PathBuf{m.active_guest(&m.state().unwrap()).unwrap()}
#[test]fn loose_profile_pair_preview_is_nonmutating_and_confirmed_import_retains_source(){let f=Fixture::new();let paths=f.pair("Owned",7);let mut m=Manager::open(&f.docs).unwrap();let before=snapshot_guest(&f.guest()).unwrap().0;let p=m.preview_raw(&paths,false).unwrap();assert_eq!(p["files_to_import"],2);assert_eq!(p["selected_profile_id"],7);assert_eq!(snapshot_guest(&f.guest()).unwrap().0,before);assert!(m.restore_raw(p["token"].as_str().unwrap(),false).is_err());apply(&mut m,&p);assert_eq!(fs::read(paths[0].clone()).unwrap(),idx(&[("Owned",7)]));let g=selected(&m);assert_eq!(fs::read(g.join("Documents/userdata/user7.dat")).unwrap(),details(1));assert!(m.can_rollback().unwrap());}
#[test]fn valid_independent_score_file_needs_no_invented_profile_or_external_bundle(){let f=Fixture::new();let p=f.put("highscores.dat",&scores());let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[p],false).unwrap();assert_eq!(v["profiles_after"],0);assert!(v["selected_profile_id"].is_null());apply(&mut m,&v);let g=selected(&m);assert_eq!(fs::read(g.join("Documents/userdata/highscores.dat")).unwrap(),scores());assert!(!g.join("Documents/userdata/users.dat").exists());assert!(!g.join("Library/Preferences").join(format!("{GAME}.plist")).exists());}
#[test]fn mixed_valid_corrupt_unknown_and_mac_metadata_are_explained_without_dropping_valid_group(){let f=Fixture::new();f.pair("Owned",1);f.put("highscores.dat",b"not a score file");f.put("readme.txt",b"not read as save");f.put(".DS_Store",b"owned metadata");let mut m=Manager::open(&f.docs).unwrap();let p=m.preview_raw(&[f.source.clone()],false).unwrap();assert_eq!(p["files_to_import"],2);assert_eq!(p["skipped"].as_array().unwrap().len(),3);apply(&mut m,&p);assert!(!selected(&m).join("Documents/userdata/readme.txt").exists());}
#[test]fn missing_new_profile_details_blocks_only_that_group_not_independent_files(){let f=Fixture::new();let p=f.put("users.dat",&idx(&[("Missing",1)]));let h=f.put("highscores.dat",&scores());let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[p,h],false).unwrap();assert_eq!(v["files_to_import"],1);assert!(!v["missing_dependencies"].as_array().unwrap().is_empty());apply(&mut m,&v);assert!(!selected(&m).join("Documents/userdata/users.dat").exists());}
#[test]fn detail_only_without_index_never_manufactures_identity(){let f=Fixture::new();let p=f.put("user7.dat",&details(2));let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[p],true).unwrap();assert_eq!(v["can_import"],false);assert_eq!(v["missing_dependencies"].as_array().unwrap().len(),1);assert_eq!(m.state().unwrap()["active"],"legacy");}
#[test]fn detail_only_can_explicitly_match_existing_ID_and_replacement_is_opt_in(){let f=Fixture::new();f.seed("Current",7);let p=f.put("user7.dat",&details(2));let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[p.clone()],false).unwrap();assert_eq!(v["can_import"],false);assert_eq!(v["conflicts"].as_array().unwrap().len(),1);let v=m.preview_raw(&[p],true).unwrap();assert_eq!(v["selected_profile_id"],7);assert!(v["notes"].as_array().unwrap().iter().any(|n|n.as_str().unwrap().contains("match existing")));apply(&mut m,&v);let g=selected(&m);assert_eq!(fs::read(g.join("Documents/userdata/user7.dat")).unwrap(),details(2));assert_eq!(fs::read(g.join("Documents/userdata/users.dat")).unwrap(),idx(&[("Current",7)]));}
#[test]fn complete_compatible_new_group_combines_known_index_rows_preserving_unaffected_current_data(){let f=Fixture::new();f.seed("Current",1);let source=f.pair("New",7);let old=snapshot_guest(&f.guest()).unwrap().0;let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&source,false).unwrap();assert_eq!(v["profiles_after"],2);apply(&mut m,&v);let files=snapshot_guest(&selected(&m)).unwrap().0;for(p,b)in old{if p!="Documents/userdata/users.dat"{assert_eq!(files[&p],b,"{p}");}}let entries=index(&files["Documents/userdata/users.dat"]).unwrap();assert_eq!(entries.iter().map(|e|e.id).collect::<Vec<_>>(),vec![1,7]);assert!(selected(&m).join("Library/Caches/empty").is_dir());assert_eq!(snapshot_guest(&f.guest()).unwrap().0["Documents/userdata/users.dat"],idx(&[("Current",1)]));}
#[test]fn same_ID_different_name_or_same_name_different_ID_are_conflicts_never_remapped(){for(name,id)in[("Different",1),("Current",7)]{let f=Fixture::new();f.seed("Current",1);let source=f.pair(name,id);f.put(&format!("stage{id}.sav"),&board());let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[f.source.clone()],true).unwrap();assert_eq!(v["can_import"],false,"{source:?} {v}");assert!(!v["conflicts"].as_array().unwrap().is_empty());assert_eq!(m.state().unwrap()["active"],"legacy");}}
#[test]fn one_complete_and_one_missing_new_group_imports_only_complete_identity(){let f=Fixture::new();let i=f.put("users.dat",&idx(&[("Good",1),("Missing",7)]));let d=f.put("user1.dat",&details(1));let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[i,d],false).unwrap();assert_eq!(v["profiles_after"],1);assert_eq!(v["missing_dependencies"].as_array().unwrap().len(),1);apply(&mut m,&v);let b=fs::read(selected(&m).join("Documents/userdata/users.dat")).unwrap();assert_eq!(index(&b).unwrap()[0].id,1);assert_eq!(index(&b).unwrap().len(),1);}
#[test]fn selected_conflicting_duplicates_never_choose_arbitrarily_and_identical_duplicates_are_skipped(){let f=Fixture::new();let a=f.put("highscores.dat",&scores());let dir=f.source.join("other");fs::create_dir(&dir).unwrap();let b=dir.join("HighScores.DAT");fs::write(&b,scores()).unwrap();let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[a.clone(),b.clone()],false).unwrap();assert_eq!(v["files_to_import"],1);assert_eq!(v["skipped"].as_array().unwrap().len(),1);let mut other=scores();other[0]=2;other.truncate(8);fs::write(&b,other).unwrap();let v=m.preview_raw(&[a,b],true).unwrap();assert_eq!(v["can_import"],false);assert_eq!(v["conflicts"].as_array().unwrap().len(),1);}
#[test]fn folder_selection_supports_Documents_userdata_replays_and_preserves_input_names_bytes(){let f=Fixture::new();let user=f.source.join("Documents/userdata/replays");fs::create_dir_all(&user).unwrap();fs::write(user.join("Replay0.peg"),replay()).unwrap();let root=user.parent().unwrap();fs::write(root.join("USERS.DAT"),idx(&[("Owned",1)])).unwrap();fs::write(root.join("USER1.DAT"),details(1)).unwrap();let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[f.source.clone()],false).unwrap();assert_eq!(v["files_to_import"],3);apply(&mut m,&v);assert_eq!(fs::read(selected(&m).join("Documents/userdata/replays/Replay0.peg")).unwrap(),replay());assert!(root.join("USERS.DAT").exists());}
#[test]fn board_files_need_an_indexed_profile_and_structural_header(){let f=Fixture::new();let b=f.put("stage7.sav",&board());let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[b.clone()],false).unwrap();assert_eq!(v["can_import"],false);drop(m);f.seed("Current",7);let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[b],false).unwrap();assert_eq!(v["files_to_import"],1);apply(&mut m,&v);}
#[test]fn parsed_scores_stats_replays_refuse_wrong_versions_truncation_bad_counts_and_trailing_bytes(){for(path,good)in[("userdata/highscores.dat",scores()),("userdata/stat_owned_1.dat",stats()),("userdata/replays/Replay0.peg",replay()),("userdata/stage1.sav",board()),("userdata/user1.dat",details(1))]{assert!(inspect_payload(path,&good).is_ok(),"{path}");let mut bad=good.clone();bad[0]=0xff;assert!(inspect_payload(path,&bad).is_err());assert!(inspect_payload(path,&good[..3]).is_err());if path.contains("highscores")||path.contains("stat_")||path.contains("replays/"){let mut bad=good.clone();bad.push(0);assert!(inspect_payload(path,&bad).is_err());}}let mut bad=scores();bad[4..8].copy_from_slice(&u32::MAX.to_le_bytes());assert!(inspect_payload("userdata/highscores.dat",&bad).is_err());}
#[test]fn traversal_links_directories_deep_paths_and_limits_are_rejected_without_publication(){let f=Fixture::new();let p=f.put("highscores.dat",&scores());let mut m=Manager::open(&f.docs).unwrap();assert!(m.preview_raw(&[f.source.join("../Selected/highscores.dat")],false).is_err());let link=f.source.join("link.dat");symlink(p,&link).unwrap();assert!(m.preview_raw(&[link],false).is_err());let bad=f.put("user1.dat",&vec![0;MAX_FILE as usize+1]);let oversized=m.preview_raw(&[bad],false).unwrap();assert_eq!(oversized["can_import"],false);assert!(!oversized["skipped"].as_array().unwrap().is_empty());assert!(m.preview_raw(&vec![f.source.clone();129],false).is_err());let mut dir=f.source.clone();for _ in 0..6{dir=dir.join("Documents");fs::create_dir(&dir).unwrap();}assert!(m.preview_raw(&[f.source.clone()],false).is_err());assert_eq!(m.state().unwrap()["active"],"legacy");for name in ["stat_","stat_a","../user1.dat","user01.dat","user2147483648.dat","Replay0.peg/evil"]{assert!(canonical(name).is_none(),"{name}");}}
#[test]fn preview_bytes_are_bound_and_current_state_or_payload_changes_require_preview_again(){let f=Fixture::new();f.seed("Current",1);let source=f.put("highscores.dat",&scores());let mut m=Manager::open(&f.docs).unwrap();let p=m.preview_raw(&[source.clone()],false).unwrap();fs::write(source,b"changed-source-after-preview").unwrap();apply(&mut m,&p);assert_eq!(fs::read(selected(&m).join("Documents/userdata/highscores.dat")).unwrap(),scores());let source=f.put("user1.dat",&details(2));let p=m.preview_raw(&[source],true).unwrap();fs::write(selected(&m).join("Library/Caches/keep.bin"),b"changed-current").unwrap();assert!(m.restore_raw(p["token"].as_str().unwrap(),true).is_err());}
#[test]fn raw_restore_interruptions_keep_old_selection_and_rollback_toggles_retained_sets(){for fail in 1..=3{let f=Fixture::new();f.seed("Current",1);let mut m=Manager::open(&f.docs).unwrap();let source=f.put("highscores.dat",&scores());let p=m.preview_raw(&[source],false).unwrap();assert!(m.restore_raw_inner(p["token"].as_str().unwrap(),true,fail).is_err());assert_eq!(m.state().unwrap()["active"],"legacy");drop(m);assert_eq!(Manager::open(&f.docs).unwrap().state().unwrap()["active"],"legacy");}let f=Fixture::new();f.seed("Current",1);let mut m=Manager::open(&f.docs).unwrap();let source=f.put("highscores.dat",&scores());let p=m.preview_raw(&[source],false).unwrap();apply(&mut m,&p);let slot=m.state().unwrap()["active"].clone();m.rollback(true).unwrap();assert_eq!(m.state().unwrap()["active"],"legacy");assert!(!f.guest().join("Documents/userdata/highscores.dat").exists());m.rollback(true).unwrap();assert_eq!(m.state().unwrap()["active"],slot);}
#[test]fn cancellation_and_new_previews_invalidate_raw_tokens(){let f=Fixture::new();let p=f.put("highscores.dat",&scores());let mut m=Manager::open(&f.docs).unwrap();let a=m.preview_raw(&[p.clone()],false).unwrap();let b=m.preview_raw(&[p],false).unwrap();assert!(m.restore_raw(a["token"].as_str().unwrap(),true).is_err());m.cancel_validation();assert!(m.restore_raw(b["token"].as_str().unwrap(),true).is_err());}
#[test]fn known_foreign_folder_identity_and_hardlinks_are_rejected(){let f=Fixture::new();f.put("highscores.dat",&scores());f.put("manifest.json",br#"{"game":"com.popcap.foreign"}"#);let mut m=Manager::open(&f.docs).unwrap();assert!(m.preview_raw(&[f.source.clone()],false).unwrap_err().contains("foreign game"));assert!(m.preview_raw(&[f.source.join("manifest.json"),f.source.join("highscores.dat")],false).is_err());fs::remove_file(f.source.join("manifest.json")).unwrap();fs::hard_link(f.source.join("highscores.dat"),f.source.join("copy.dat")).unwrap();assert!(m.preview_raw(&[f.source.join("highscores.dat")],false).is_err());assert!(m.preview_raw(&[f.source.clone()],false).is_err());assert_eq!(m.state().unwrap()["active"],"legacy");}
#[test]fn current_invalid_profile_preference_is_not_silently_changed(){let f=Fixture::new();f.seed("Current",1);let pref=f.guest().join("Library/Preferences").join(format!("{GAME}.plist"));let mut d=plist::Dictionary::new();d.insert("CurUser".into(),plist::Value::Integer(7.into()));plist::Value::Dictionary(d).to_file_xml(pref).unwrap();let source=f.put("highscores.dat",&scores());let mut m=Manager::open(&f.docs).unwrap();assert!(m.preview_raw(&[source],false).is_err());assert_eq!(m.state().unwrap()["active"],"legacy");}
fn text(b:&mut Vec<u8>,s:&str){b.extend_from_slice(&(s.len()as u16).to_le_bytes());b.extend_from_slice(s.as_bytes());}
#[test]fn populated_score_and_stats_containers_validate_counts_text_and_exact_end(){let mut h=Vec::from(3u32.to_le_bytes());h.extend_from_slice(&1u32.to_le_bytes());text(&mut h,"owned-level");h.extend_from_slice(&2u32.to_le_bytes());for name in ["Owned","雪😀"]{text(&mut h,name);h.extend_from_slice(&12345u32.to_le_bytes());}h.extend_from_slice(&[0;4]);assert!(inspect_payload("userdata/highscores.dat",&h).is_ok());for n in [7,h.len()-1]{assert!(inspect_payload("userdata/highscores.dat",&h[..n]).is_err());}let mut s=Vec::from(3u32.to_le_bytes());s.extend_from_slice(&[0;4]);text(&mut s,"owned-source");s.extend_from_slice(&[0;4+12*4+16*8]);s.extend_from_slice(&1u32.to_le_bytes());text(&mut s,"owned-level");s.extend_from_slice(&[0;44]);s.extend_from_slice(&1u32.to_le_bytes());s.extend_from_slice(&3u32.to_le_bytes());s.extend_from_slice(&[0;8]);s.extend_from_slice(&[0;12*4+16*8]);s.extend_from_slice(&1u32.to_le_bytes());text(&mut s,"owned-stage");s.extend_from_slice(&[0;44]);assert!(inspect_payload("userdata/stat_owned_1.dat",&s).is_ok());assert!(inspect_payload("userdata/stat_owned_1.dat",&s[..s.len()-1]).is_err());}
#[test]fn zip_among_loose_files_is_explained_without_blocking_independent_valid_files(){let f=Fixture::new();let h=f.put("highscores.dat",&scores());let z=f.put("backup.zip",b"not read through raw import");let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[h,z],false).unwrap();assert_eq!(v["files_to_import"],1);assert_eq!(v["skipped"].as_array().unwrap().len(),1);assert!(v["skipped"][0]["reason"].as_str().unwrap().contains("Restore Backup ZIP"));}
#[test]fn oversized_file_is_skipped_without_losing_a_valid_independent_file(){let f=Fixture::new();let h=f.put("highscores.dat",&scores());let big=f.put("user1.dat",&vec![0;MAX_FILE as usize+1]);let mut m=Manager::open(&f.docs).unwrap();let v=m.preview_raw(&[big,h],false).unwrap();assert_eq!(v["files_to_import"],1);assert!(v["skipped"][0]["reason"].as_str().unwrap().contains("16MiB"));apply(&mut m,&v);assert!(!selected(&m).join("Documents/userdata/user1.dat").exists());}
